#nullable disable

using System.IO;
using Match3.Configs;
using Match3.Core.Models;
using UnityEditor;
using UnityEngine;

namespace Match3.Editor
{
    /// <summary>
    /// Генератор StageStoryConfig ассетов для всех 5 стран (50 этапов).
    /// Запуск: Match3 / Generate Story Configs
    /// Ассеты создаются в Assets/Match3/Configs/WorldMap/Country{N}_{Name}/Stories/
    /// </summary>
    public static class StoryConfigGenerator
    {
        private const string BasePath = "Assets/Match3/Configs/WorldMap";

        [MenuItem("Match3/Generate Story Configs")]
        public static void Generate()
        {
            GenerateEgypt();
            GenerateGreece();
            GenerateChina();
            GenerateMaya();
            GenerateIndia();

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            Debug.LogWarning("StoryConfigGenerator: все 50 StageStoryConfig ассетов созданы.");
        }

        // ── Helpers ───────────────────────────────────────────────────────────

        private static StageStoryConfig CreateAsset(string countryFolder, string fileName)
        {
            var dir = $"{BasePath}/{countryFolder}/Stories";
            if (!Directory.Exists(dir))
                Directory.CreateDirectory(dir);

            var path   = $"{dir}/{fileName}.asset";
            var exists = AssetDatabase.LoadAssetAtPath<StageStoryConfig>(path);
            if (exists != null) return exists;

            var asset = ScriptableObject.CreateInstance<StageStoryConfig>();
            AssetDatabase.CreateAsset(asset, path);
            return asset;
        }

        private static StorySlide Slide(string text, string locId = "")
        {
            var s = new StorySlide();
            typeof(StorySlide)
                .GetField("<FallbackText>k__BackingField",
                    System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)
                ?.SetValue(s, text);
            typeof(StorySlide)
                .GetField("<LocalizationId>k__BackingField",
                    System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)
                ?.SetValue(s, locId);
            return s;
        }

        private static LevelStoryData LevelData(
            StorySlide start, StorySlide win, StorySlide lose)
        {
            var d = new LevelStoryData();
            var t = typeof(LevelStoryData);
            var f = System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance;
            t.GetField("<StartStory>k__BackingField", f)?.SetValue(d, start);
            t.GetField("<WinStory>k__BackingField",   f)?.SetValue(d, win);
            t.GetField("<LoseStory>k__BackingField",  f)?.SetValue(d, lose);
            return d;
        }

        private static void Apply(
            StageStoryConfig cfg,
            StorySlide       stageSelect,
            LevelStoryData   lvl0,
            LevelStoryData   lvl1,
            LevelStoryData   lvl2)
        {
            var t = typeof(StageStoryConfig);
            var f = System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance;
            t.GetField("<StageSelectStory>k__BackingField", f)?.SetValue(cfg, stageSelect);
            t.GetField("<LevelStories>k__BackingField",     f)?.SetValue(cfg,
                new LevelStoryData[] { lvl0, lvl1, lvl2 });
            EditorUtility.SetDirty(cfg);
        }

