                    LevelData(
                        Slide(lvls[0].start, $"{locPrefix}_l1_start"),
                        lvls[0].win  != null ? Slide(lvls[0].win,  $"{locPrefix}_l1_win")  : null,
                        Slide(lvls[0].lose, $"{locPrefix}_l1_lose")),
