                    LevelData(
                        Slide(lvls[2].start, $"{locPrefix}_l3_start"),
                        lvls[2].win  != null ? Slide(lvls[2].win,  $"{locPrefix}_l3_win")  : null,
                        Slide(lvls[2].lose, $"{locPrefix}_l3_lose")));
            }
