            var stageData = new (string select, (string start, string win, string lose)[] levels)[]
            {
                ("Пирамида Кукулькана — «Эль Кастильо». Построена так что в дни равноденствия тень создаёт силуэт змея. Это не магия — это математика. Звёздные Камни здесь, в основании пирамиды. Собери пять цветов — и мы начнём расшифровку пророчества.", new[] { ("Основание пирамиды — девяносто одна ступень на каждой из четырёх сторон плюс верхняя платформа. Триста шестьдесят пять. Один год. Майя считали точно. Ищи закономерность и собирай.", null as string, "Закономерность не найдена. Или найдена но не та. Пересчитай — и снова."), ("Камни реагируют на положение солнца! В этот час — больше красных и синих. Это не случайность, это астрономия в камне. Собирай пока солнце в нужном положении.", null, "Солнце сдвинулось немного. Ничего — оно вернётся примерно туда же. Ещё раз!"), ("Последние Звёздные Камни у основания главной лестницы. Видишь как они мерцают? Это отражение звёзд — даже днём. Необъяснимо с точки зрения физики. Запишу это. Потом. Сначала собери.", "Первая группа Звёздных Камней собрана! Пророчество частично расшифровано: «Когда Змей увидит свет звёзд — пробудится». Всё связано. Идём в Ушмаль.", "Лестница держит последние камни. Майя строили на тысячелетия. Мы справимся за одну попытку — ещё раз!") }),
                ("Ушмаль — «Трижды Построенный». Здесь хранятся Камни Цикла — особый тип Звёздных Камней. Они фиксируют время. Собери их — и узнаем когда именно возвращается Кукулькан.", new[] { ("Пирамида Магов — по легенде построена за ночь карликом-магом. По факту — несколько веков строительства. Легенды всегда упрощают. Камни Цикла рассыпаны вокруг. Начинаем собирать.", null, "Карлик-маг справился за ночь — мы за несколько попыток. Нормально. Снова!"), ("Квадрат монахов — четыре здания вокруг двора. Камни Цикла лежат по периметру в строгом порядке. Собирай по кругу — это важно для расшифровки временного кода.", null, "Порядок нарушен. Временной код сбился. Начнём заново — круг должен быть замкнут!"), ("Последние Камни Цикла у Пирамиды Магов! Когда соберём их — узнаем дату. Я немного волнуюсь. Это не суеверие — это научный интерес. Совсем другое.", "Дата расшифрована! Кукулькан возвращается в день зимнего солнцестояния — через двадцать дней. Это не легенда исследователь. Это реальное событие. Нам нужно успеть.", "Временной код почти собран — ещё несколько камней! Снова, быстро!") }),
                ("Тикаль — город в джунглях. Здесь влажно, жарко и... почему лёд? В тропическом лесу магический лёд. Кто бы это ни сделал, он использует магию которую я не понимаю. Это неприятно.", new[] { ("Лёд в джунглях — температурная аномалия. Кто бы это ни сделал, он использует магию которую я не понимаю. Это неприятно. Разбиваем лёд матчами рядом и собираем Камни Движения.", null, "Аномалия оказалась устойчивей чем я рассчитала. Пересчитаю коэффициент и снова!"), ("Один блок льда разрушен! Под ним — наскальные рисунки. Кукулькан изображён именно здесь, в Тикале. Это место значимо для пророчества. Продолжай!", null, "Рисунки ждут. Мы ждём. Только секунду — и снова к делу!"), ("Последний ледяной блок у главного храма! Пророчество говорит: «Движение камней — движение звёзд». Разбей лёд — и звёзды сдвинутся на нужные позиции.", "Камни собраны! И... рисунки на стенах засветились. Я написала «необъяснимо» в блокноте. Это первый раз за три года исследований. Идём в Паленке — там ответы.", "Звёзды ждут нашего сигнала. Дадим им — ещё раз!") }),
                ("Паленке — город где найдена гробница царя Пакаля. Четыре ледяных замка. Нам нужны Камни Перехода хранящиеся внутри гробницы.", new[] { ("Гробница Пакаля запечатана льдом — символично. Нам нужны Камни Перехода хранящиеся внутри. Разбиваем первый ледяной замок — методично, как Пакаль строил свой город.", null, "Методично не вышло. Пакаль строил лучше. Попробуем снова — точнее!"), ("Форма ромба — символ звезды в календаре майя! Пакаль зашифровал расположение льда в форму звезды. Это не случайность — это подсказка. Собирай по диагоналям и разбивай лёд в правильном порядке.", null, "Звёздный порядок нарушен. Пакаль был умнее чем я думала. Уважаю — и снова!"), ("Последние ледяные замки у самой плиты Пакаля! Камни Перехода прямо под плитой — я уже вижу их свечение. Разбей лёд — и плита откроет тайну которую Пакаль скрывал тысячу лет.", "Камни у нас! И плита открылась... там написано: «Кукулькан вернётся через того кто соберёт Семь Звёзд». Я была права насчёт математики. И немного не права насчёт магии.", "Плита ждёт. Мы не заставим её ждать долго — ещё раз!") }),
                ("Копан — город иероглифов. Ящики с архивными камнями заблокировали подвалы плюс магический лёд. Кто-то активно не хочет чтобы мы нашли Камни Истории. Это значит они важны.", new[] { ("Архивные ящики хранят историю. Странно что их использовали как заграждение. Разбиваем аккуратно — внутри могут быть ценные записи кроме нужных нам камней. Ну, камни важнее. Наверное.", null, "История сопротивляется. Как обычно. Но мы её изучаем — и побеждаем. Снова!"), ("Форма песочных часов — время. Время записано в каждом иероглифе этого города. Лёд и ящики в узкой части — там самое ценное. Пробиваемся к центру!", null, "Центр держится. Время работает против нас — двадцать дней уже не двадцать. Быстрее!"), ("Последние препятствия у Алтаря Q — там записана история шестнадцати царей! И Камни Истории там же. Разбиваем всё что мешает — и берём камни. Цари поймут.", "Камни Истории собраны! На них — предупреждение: «Не дай Тёмному Змею перехватить Звёзды». Тёмный Змей? Нам нужно в Монте-Альбан — там шестой город.", "Алтарь держит тайну. Шестнадцать царей охраняют. Мы настойчивее — ещё раз!") }),
                ("Монте-Альбан — здесь жили сапотеки, предшественники майя. Шесть цветов камней — шесть созвездий которые должны выстроиться при возвращении Кукулькана. И четыре священных цепи запирают обсерваторию.", new[] { ("Шесть цветов — шесть созвездий Змея. Цепи мешают их соединению. Рвём цепи и собираем все шесть — только вместе они работают.", null, "Созвездия не выстроились. Одна цепь ещё держит. Снова — и точнее!"), ("Обсерватория реагирует! Когда камни собираются — отверстия в стенах начинают пропускать свет в нужные точки. Это не магия — это архитектура. Невероятная архитектура. Продолжай!", null, "Свет не попал в точку. Архитектура требует точности. Ещё раз — и точнее!"), ("Финальные цепи у главного алтаря! За ними — Камни Созвездия, последние в Монте-Альбан. Разрываем цепи — и шесть созвездий Змея выстроятся впервые за тысячу лет!", "СОЗВЕЗДИЯ ВЫСТРОИЛИСЬ! Свет бьёт через все отверстия одновременно! Это невозможно без магии. Признаю. И ещё: я вижу Тёмного Змея — он наблюдает с горы. Нам нужно в последний город.", "Последняя цепь держит. Но Змей не должен победить — ещё раз!") }),
                ("Теотиуакан — «Место где рождаются боги». Тёмный Змей пришёл сюда первым и выставил все преграды: ящики, цепи. Он хочет поглотить Звёздные Камни прежде чем Кукулькан вернётся. Финальный город.", new[] { ("Аллея Мёртвых заблокирована ящиками. Тёмный Змей работал быстро. Но мы работаем умнее. Разбираем ящики и ищем Камни Рождения — они самые яркие, почти как звёзды.", null, "Тёмный Змей доволен. Рано. Ещё раз — и ящики не устоят!"), ("Пирамида Солнца! Самая большая здесь. Цепи у подножия — Тёмный Змей запер её. Он боится что Солнечная Пирамида усилит Кукулькана. Правильно боится. Рвём цепи!", null, "Солнечная Пирамида ждёт освобождения. Мы не подведём — снова!"), ("Пирамида Луны — финал. Все Звёздные Камни должны сойтись здесь. Тёмный Змей стоит на вершине и смотрит. Пусть смотрит. Разнеси последние преграды и собери все шесть цветов — Кукулькан услышит!", "ВСЕ ЗВЁЗДНЫЕ КАМНИ СОБРАНЫ! Небо над Теотиуаканом загорелось! Тёмный Змей кричит и отступает! И вот — Кукулькан! Он... огромный. И прекрасный. Смотрит на нас. Я молчу. Первый раз за очень долго.", "Тёмный Змей думает что победил. Он ошибается — последний раз, и Кукулькан свободен!") }),
                ("Тулум — город на берегу моря. Кукулькан оставил здесь послание — финальное благодарение тем кто его освободил. Но Тёмный Змей в отступлении заморозил побережье и скрутил проходы цепями.", new[] { ("Ледяное побережье — красиво и неуместно. Тёмный Змей из последних сил. Разбиваем лёд — море должно вернуться к берегу. Камни Благодарения под льдом, они тёплые — почти горячие.", null, "Море ждёт. Мы ненадолго — снова!"), ("Цепи у городских ворот — Тёмный Змей хотел запереть послание навсегда. Это его последняя ставка. Рвём цепи — и ворота откроются.", null, "Последняя ставка Тёмного Змея — крепкая. Но не крепче нашей решимости. Снова!"), ("Алтарь у берега моря — там финальные Камни Благодарения. Разбиваем последние преграды и читаем послание Кукулькана.", "Послание прочитано: «Спасибо тем кто не побоялся считать звёзды». Я... я считала звёзды всю жизнь. Это для меня. Кукулькан улетает в небо. Небо над Тулумом чистое.", "Финальное послание ждёт. Немного терпения — и оно наше!") }),
                ("Священный Сенот Чичен-Ица — природный колодец где майя делали подношения богам. Круг замкнулся — мы начали здесь и заканчиваем здесь. Последние Камни Звёздного Ритуала лежат на дне.", new[] { ("Сенот хранит всё что в него бросали — монеты, камни, память. Наши Звёздные Камни отзываются на воду — видишь как они светятся? Разбиваем лёд и рвём цепи — позволяем камням вернуться к людям.", null, "Вода прячет тайны. Но мы умеем их находить — снова!"), ("Форма Т — форма Кукулькана в полёте. Сенот построен так что отражает созвездие Змея в полнолуние. Майя знали астрономию лучше чем мы думали. Продолжаем — финал рядом.", null, "Отражение прервалось. Восстановим — ещё раз!"), ("Последние Камни Ритуала! Лёд и цепи у самого края сенота. Соберём их — и ритуал завершён. Пророчество исполнено. Двадцать дней назад я не верила в это. Сейчас — верю.", "РИТУАЛ ЗАВЕРШЁН! Сенот засветился всеми шестью цветами! Кукулькан прощается с нами из звёзд. Пророчество было правдой. Математика и магия — оказывается одно и то же. Запишу это.", "Последний момент — он наш! Ещё раз — и ритуал завершён!") }),
                ("Кукулькан оставил нам подарок — доступ к Небесной Карте майя. Все шесть созвездий Змея видны одновременно. Нужно собрать Камни всех шести созвездий чтобы карта ожила. Это уже не пророчество — это награда.", new[] { ("Небесная Карта реагирует на порядок сбора! Каждый цвет — одно созвездие. Собирай по одному — и карта будет разворачиваться шаг за шагом. Я делаю заметки.", null, "Карта не развернулась до конца. Заметки пополнились: «Порядок важен». Снова!"), ("Пять созвездий на карте! Осталось шестое — Корона Змея. Когда соберём последний цвет — увидим полную карту звёздного неба майя. Впервые за тысячу лет.", null, "Корона не легла на место. Чуть-чуть — и она наша. Ещё раз!"), ("Финальные камни всех шести созвездий! Кукулькан смотрит на нас из звёзд. Собери их — и небесная карта майя будет открыта навсегда.", "НЕБЕСНАЯ КАРТА ОТКРЫТА! Все созвездия на месте. Кукулькан светится ярче всех. Ишель молчит минуту... потом говорит: «Я пересмотрю несколько глав своей диссертации». Это значит — мы изменили историю.", "Последние камни ждут своего места в карте. Найдём его — снова!") }),
            };

            for (var i = 0; i < stageData.Length; i++)
            {
                var (sel, lvls) = stageData[i];
                var fileName = i < 9 ? $"Stage0{i + 1}_Story" : "Stage10_Bonus_Story";
                var cfg = CreateAsset(country, fileName);
                var locPrefix = $"maya_{i + 1:D2}";
                Apply(cfg,
                    Slide(sel, $"{locPrefix}_select"),
                    LevelData(
                        Slide(lvls[0].start, $"{locPrefix}_l1_start"),
                        lvls[0].win  != null ? Slide(lvls[0].win,  $"{locPrefix}_l1_win")  : null,
                        Slide(lvls[0].lose, $"{locPrefix}_l1_lose")),
                    LevelData(
                        Slide(lvls[1].start, $"{locPrefix}_l2_start"),
                        lvls[1].win  != null ? Slide(lvls[1].win,  $"{locPrefix}_l2_win")  : null,
                        Slide(lvls[1].lose, $"{locPrefix}_l2_lose")),
                    LevelData(
                        Slide(lvls[2].start, $"{locPrefix}_l3_start"),
                        lvls[2].win  != null ? Slide(lvls[2].win,  $"{locPrefix}_l3_win")  : null,
                        Slide(lvls[2].lose, $"{locPrefix}_l3_lose")));
            }
        }

        // ══════════════════════════════════════════════════════════════════════
        // INDIA
        // ══════════════════════════════════════════════════════════════════════

        private static void GenerateIndia()
        {
            const string country = "Country4_India";

            var stageData = new (string select, (string start, string win, string lose)[] levels)[]
            {
                ("Слушай, незнакомец! Я — принц Арджун, наследник трона которого у меня нет потому что маг Кали похитил Лотос Индры! Без него церемония коронации невозможна. Первый лепесток спрятан здесь, в Дворце Агры! Помоги найти!", new[] { ("Дворец Агры — жемчужина моего царства! Шесть цветов — шесть богов которым посвящён Лотос. Собирай все!", null as string, "Кали смеётся над нами! Я слышу его смех в стенах дворца. Может быть это эхо. Но мы не сдаёмся — снова!"), ("Залы дворца отзываются на камни — слышишь звон? Это магия Лотоса Индры — она рассеяна по всем камням этого места. Собирай быстрее — магия усиливается вместе с нами!", null, "Магия ослабла. Мы не успели её поймать. Но она никуда не денется — снова!"), ("Тронный зал! Первый лепесток спрятан под мозаикой пола — я чувствую его тепло сквозь мрамор. Соберём все камни — мозаика откроется и лепесток наш!", "ПЕРВЫЙ ЛЕПЕСТОК НАЙДЕН! Он золотой и тёплый как солнце! Кали думал что я не найду... ошибся. Нас двое — и мы только начали! Следующий лепесток в Джайпуре.", "Мозаика не открылась. Кали заколдовал её крепко. Но мы крепче его заклинаний — ещё раз!") }),
                ("Джайпур — Розовый Город! Всё здесь розовое — в честь цвета гостеприимства. Кали выбрал именно это место чтобы спрятать второй лепесток — наверное из злобы. Найдём лепесток и вернём Джайпуру его честь!", new[] { ("Хава Махал — Дворец Ветров! Тысяча девятьсот пятьдесят три окна — я считал в детстве. Камни рассыпаны по этажам как лепестки роз. Собирай все шесть цветов — второй лепесток спрятан на последнем этаже.", null, "Ветер уносит камни — в метафорическом смысле. В буквальном смысле — я просто не успел. Снова!"), ("Янтр-Мантр — обсерватория астрономов! Камни здесь расположены по звёздным позициям — собирай в том порядке который соответствует созвездию Индры. Или просто собирай всё что видишь — тоже работает.", null, "Звёздный порядок нарушен. Астрологи недовольны. Как и я. Ещё раз!"), ("Амер Форт! Самая высокая точка Джайпура — и второй лепесток где-то здесь в кладке стен. Последние камни у южной башни. Соберём их — и стены сами укажут где лепесток!", "Второй лепесток! Серебристый как лунный свет! Кали, ты прячешь их в красивых местах — это единственное что тебя оправдывает. Пока что. Летим в Варанаси!", "Южная башня держит тайну. Как все хорошие башни. Ещё раз — и тайна наша!") }),
                ("Варанаси — священнейший город! Здесь Ганга берёт начало. И здесь Кали посмел использовать магический лёд! В святом месте! Это кощунство. Третий лепесток под ледяными запорами у берега реки.", new[] { ("Гаты — ступени к реке. Кали заморозил нижние гаты где лежит лепесток. Ганга недовольна — я вижу по волнам. Разбиваем лёд и освобождаем берег!", null, "Ганга ждёт. Мы не заставим её ждать долго — снова!"), ("Храм Каши Вишванатха! Посвящён Шиве — самому могущественному из богов. Шива видит наши усилия. Второй ледяной блок у входа в храм. Разбиваем — и Шива нам поможет!", null, "Шива проверяет нашу веру. Мы верим что справимся — снова!"), ("Последний лёд у главного гата! Третий лепесток светится под водой — голубой как небо в сезон дождей. Соберём камни, разобьём лёд — и Варанаси вернёт своё священное сокровище!", "Третий лепесток! Голубой и прохладный — он гасит гнев! Может быть... может быть я должен поговорить с Кали прежде чем наказывать его? Нет, нет. Сначала все лепестки. Потом думаем.", "Гата ждёт освобождения. Ещё один шаг — и лепесток наш!") }),
                ("Кхаджурахо — храмы посвящённые гармонии. Кали запечатал четвёртый лепесток четырьмя ледяными замками. Четыре замка — четыре стороны света — четыре испытания. Начинаем!", new[] { ("Северный замок — первое испытание. Кали думал что я остановлюсь уже здесь. Он не знает меня. И не знает тебя! Разбиваем северный лёд и идём по часовой стрелке — как солнце.", null, "Солнце тоже иногда прячется за облака. Это временно. Снова!"), ("Два замка разрушены! Храмы сами помогают нам — видишь как камни к нам тянутся? Гармония на нашей стороне. Ещё два замка — восточный и западный.", null, "Гармония нарушена. Восстановим — ещё раз!"), ("Последние два замка — южный и центральный. Четвёртый лепесток пульсирует внутри — оранжевый как закат! Соберём последние камни — и гармония Кхаджурахо восстановлена!", "Четвёртый лепесток — оранжевый, тёплый, живой! Ещё три — и корона моя. Летим на юг!", "Южный и центральный замки держатся. Пусть недолго — ещё раз!") }),
                ("Дели — столица! Кали спрятал пятый лепесток в Джама-Масджид — великой мечети. Каменные ящики загромоздили внутренний двор. Расчистим двор и найдём лепесток. Уважая место.", new[] { ("Внутренний двор мечети — место покоя для тысяч людей. Ящики здесь неуместны — это работа Кали, не хозяев. Разбираем аккуратно и ищем лепесток среди старинных плит.", null, "Покой нарушен. Восстановим и его, и наш путь — снова!"), ("Минарет! Кали заблокировал подход к минарету ящиками — там что-то важное. Лепесток или подсказка к нему. Разбираем ящики и поднимаемся выше.", null, "Минарет высок, ящики тяжелы. Но мы упорнее — следующая попытка!"), ("Главный портал мечети! Последние ящики здесь — и за ними сияет пятый лепесток. Зелёный как листья священного дерева. Разбиваем — и он наш!", "Пятый лепесток, зелёный! Он пах жасмином когда я взял его в руки. Кали... я уже почти понимаю тебя. Зависть — страшная вещь. Но я всё равно хочу получить корону. Два лепестка осталось!", "Портал держит лепесток. Но не вечно — ещё раз!") }),
                ("Майсур — дворец с тысячью комнат! Шестой лепесток где-то внутри. Кали опутал весь дворец цепями — буквально. Четыре огромных цепных замка запирают главные залы. Разрываем цепи!", new[] { ("Тысяча комнат и четыре главных цепи. Начнём с той что у парадного входа — она самая видимая. Кали сделал её самой заметной чтобы напугать. Не напугал! Рвём первую!", null, "Цепь не поддалась. Кали не зря выбрал её для входа. Но мы прошли пять лепестков — пройдём и шестой. Снова!"), ("Зал Слонов! Здесь проходили церемонии коронации... включая ту которую я жду. Цепи здесь в два слоя — Кали знал что это место мне важно. Тем больше причин разорвать их!", null, "Зал Слонов ждёт меня. Я тоже жду — и это придаёт силы. Снова!"), ("Тронный зал Майсура! Последние цепи здесь — и шестой лепесток на самом троне. Кали посадил его на чужой трон — символично и обидно. Рвём цепи и возвращаем лепесток туда где ему место!", "Шестой лепесток — фиолетовый! Цвет царской мудрости! Кали... ты спрятал его на троне. Ты мечтал сам сесть на трон? Я понимаю эту мечту. Но не твои методы. Последний лепесток — и поговорим.", "Тронный зал ждёт законного наследника. Я ждать умею — но лучше не надо. Снова!") }),
                ("Гоа — берег моря, последнее место. Кали бежал сюда с седьмым лепестком. Лёд и цепи — он использовал всё что осталось. Последний лепесток — и Лотос Индры снова целый!", new[] { ("Кали на берегу! Я вижу его следы — лёд там где не должно быть льда у тропического моря. Он бежал впопыхах — не так тщательно расставил преграды. Его слабость — наш шанс. Вперёд!", null, "Кали оказался тщательнее чем казалось. Уважение — и снова!"), ("Церковь Бом Жезус — здесь покоятся реликвии святого Франциска. Кали спрятался в её тени. Ломаем цепи у входа — и последний лепесток близко. Финал этого пути!", null, "Тень Кали ещё длинная. Но солнце движется — и мы тоже. Снова!"), ("Берег! Кали стоит у воды и держит последний лепесток. Лёд и цепи — его финальная защита. Разбей их — и лепесток упадёт. Кали... я уже не злюсь. Просто хочу закончить это.", "СЕДЬМОЙ ЛЕПЕСТОК! ЛОТОС ИНДРЫ ЦЕЛЫЙ! Кали падает на колени... и плачет. Он говорит: «Я хотел стать важным. Я не знал другого способа». Я смотрю на него... и протягиваю руку. Пойдём на коронацию вместе — как советник.", "Последний лепесток! Так близко! Финальный рывок — снова!") }),
                ("Возвращаемся в Агру! Дворец коронации ждёт. Но Советник Кали говорит что его старые заклинания ещё держатся в стенах. Нужно очистить дворец от остатков магии. Очистим их вместе.", new[] { ("Тронный зал Агры — здесь пройдёт коронация. Остатки льда Кали тают сами — но медленно. Помогаем им. Собираем камни и разбиваем последний лёд — тронный зал должен сиять!", null, "Лёд держится — старая магия упряма. Но не упрямее нашего желания. Снова!"), ("Советник Кали помогает советом! Говорит — цепи ослабнут если собрать камни в определённом порядке. Я немного ему верю. Немного. Проверяем — и рвём цепи!", null, "Совет Кали не сработал. Или я неправильно понял. Обсудим потом — снова своим умом!"), ("Финальные преграды у трона! Лотос Индры в моих руках — все семь лепестков. Разобьём последний лёд и разорвём последнюю цепь — и церемония начнётся. Это момент за которым я шёл всю жизнь!", "ДВОРЕЦ ОЧИЩЕН! Трон свободен! Лотос Индры сияет... я кладу его на место. Советник Кали стоит рядом — выглядит неловко но честно. Коронация начинается. Последний этап — ритуал Индры!", "Трон почти готов принять меня! Последнее усилие — снова!") }),
                ("Ритуал Индры — финальная часть коронации. Семь алтарей, семь лепестков, семь испытаний. Остатки магии Кали сгустились здесь в последний раз. Очищаем каждый алтарь — и ритуал начнётся.", new[] { ("Первые алтари очищаются легко — магия Кали здесь слабая, он не успел укрепить. Собирай камни и освобождай алтари. Каждый чистый алтарь — один шаг к трону!", null, "Первые алтари ещё держатся. Это только начало ритуала — мы справимся. Снова!"), ("Центральные алтари — самые важные. Здесь лепестки начинают соединяться в Лотос. Лёд и цепи крепче — но Лотос Индры помогает нам. Я чувствую его тепло. Финал близко!", null, "Лотос тоже чувствует что мы близко! Он ждёт нас — ещё раз!"), ("Последний алтарь! Лотос Индры расцветает — все семь лепестков соединяются прямо сейчас. Соберём финальные камни — и ритуал завершён. Принц Арджун становится царём.", "РИТУАЛ ЗАВЕРШЁН! ЛОТОС ИНДРЫ РАСЦВЁЛ! Индра смотрит с небес... кивает. Советник Кали плачет — теперь уже от радости. Я... я царь. Спасибо тебе, незнакомец. Ты пришёл в нужное время. Как и должно было быть.", "Последний алтарь! Последний шаг! Мы так близко к финалу — ещё раз, это наш момент!") }),
                ("Индра лично приглашает нас в свой Небесный Сад! Там растут цветы всех шести цветов — каждый связан с одним из даров: мудрость, сила, доброта, красота, смелость, щедрость. Собери все шесть — и получишь благословение самого Индры.", new[] { ("Небесный Сад прекрасен. Шесть цветов лотосов, шесть даров. Кали шёпотом просит «мудрость и доброту». Я делаю вид что не слышу, но слышу. Собираем!", null, "Сад не раскрылся до конца. Терпение — дар которого мне пока не хватает. Снова!"), ("Пять цветов собраны! Шестой — самый редкий — в центре сада. Это дар Щедрости. Кали смотрит на него особенно внимательно. Думаю он понял кое-что важное. Продолжаем!", null, "Шестой дар ускользает. Щедрость действительно редка. Но мы найдём её — снова!"), ("Финальные камни всех шести цветов! Индра смотрит. Кали держит меня за руку — неловко но искренне. Собери все шесть — и Небесный Сад подарит нам то что мы заслужили.", "ВСЕ ШЕСТЬ ДАРОВ ПОЛУЧЕНЫ! Индра говорит: «Тот кто смог простить — уже мудр». Это про меня. И про Кали. Советник Кали светится буквально — он получил свой дар. Мы оба. Незнакомец — твой дар тоже здесь. Заслуженный.", "Последние камни в Небесном Саду ждут. Мы тоже ждём — только одну секунду. Снова!") }),
            };

            for (var i = 0; i < stageData.Length; i++)
            {
                var (sel, lvls) = stageData[i];
                var fileName = i < 9 ? $"Stage0{i + 1}_Story" : "Stage10_Bonus_Story";
                var cfg = CreateAsset(country, fileName);
                var locPrefix = $"india_{i + 1:D2}";
                Apply(cfg,
                    Slide(sel, $"{locPrefix}_select"),
                    LevelData(
                        Slide(lvls[0].start, $"{locPrefix}_l1_start"),
                        lvls[0].win  != null ? Slide(lvls[0].win,  $"{locPrefix}_l1_win")  : null,
                        Slide(lvls[0].lose, $"{locPrefix}_l1_lose")),
                    LevelData(
                        Slide(lvls[1].start, $"{locPrefix}_l2_start"),
                        lvls[1].win  != null ? Slide(lvls[1].win,  $"{locPrefix}_l2_win")  : null,
                        Slide(lvls[1].lose, $"{locPrefix}_l2_lose")),
                    LevelData(
                        Slide(lvls[2].start, $"{locPrefix}_l3_start"),
                        lvls[2].win  != null ? Slide(lvls[2].win,  $"{locPrefix}_l3_win")  : null,
                        Slide(lvls[2].lose, $"{locPrefix}_l3_lose")));
            }
        }
    }
}
